import { GoogleGenAI, Type } from "@google/genai";
import type { GroundingChunk, AnalysisResult, TerrainAnalysis } from '../types';

// Initialization following Google GenAI SDK strict guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToGenerativePart = async (file: File) => {
  const base64EncodedDataPromise = new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: { data: await base64EncodedDataPromise, mimeType: file.type },
  };
};

export const analyzeCrop = async (imageFile: File, userLocation?: string): Promise<AnalysisResult> => {
    // Task 1: Analyze the image for pests/diseases
    const imageAnalysisPromise = async () => {
        const imagePart = await fileToGenerativePart(imageFile);

        // Strict, structured output prompt
        const prompt = `
            Atue como um agrônomo sênior especialista em fitopatologia. Analise esta imagem de uma cultura agrícola.

            Retorne APENAS as informações técnicas nos tópicos abaixo, formatados rigorosamente em Markdown. Não use frases de introdução (como "Aqui está a análise") ou conclusão. Seja direto e objetivo.

            ## 🔍 Diagnóstico
            [Nome científico e comum da praga, doença ou deficiência. Se a planta estiver saudável, informe apenas "Planta Saudável".]

            ## 📝 Sintomas Identificados
            [Liste os sintomas visuais observados na imagem de forma objetiva]

            ## 💊 Tratamento Recomendado
            [Liste defensivos químicos (princípios ativos), biológicos ou métodos culturais recomendados para controle imediato]

            ## 🛡️ Medidas Preventivas
            [Dicas para evitar reincidência]

            Se a imagem não for de uma planta ou cultura agrícola, responda apenas: "Imagem inválida: Não foi possível identificar uma cultura agrícola."
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: [{ parts: [imagePart, {text: prompt}] }],
        });

        return response.text || "Não foi possível gerar a análise.";
    };

    // Task 2: Find nearby stores using Maps Grounding based on user location
    const findStoresPromise = async () => {
        const locationQuery = userLocation && userLocation.trim() !== '' 
            ? `perto de ${userLocation}` 
            : "próximas a minha localização atual";

        const prompt = `Liste casas agropecuárias ${locationQuery}.`;

        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                tools: [{googleMaps: {}}],
            },
        });

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

        return {
            storesText: response.text || "Não foi possível encontrar lojas.",
            groundingChunks: groundingChunks as GroundingChunk[]
        };
    };

    const [diagnosis, storesData] = await Promise.all([
        imageAnalysisPromise(),
        findStoresPromise(),
    ]);

    return {
        diagnosis,
        stores: storesData.storesText,
        groundingChunks: storesData.groundingChunks
    };
};

export const analyzeTerrain = async (location: string): Promise<TerrainAnalysis> => {
    const prompt = `
        Você é um sistema de topografia avançado. Analise a região de: "${location}".
        Use o Google Maps para encontrar dados REAIS sobre a geografia, hidrografia e infraestrutura próxima.

        Gere uma resposta em JSON contendo:
        1. locationName: O nome formal do local encontrado.
        2. report: Um relatório técnico agronômico em Markdown (Clima, Relevo, Solo estimado, Culturas indicadas).
        3. roughness: Um número decimal de 0.0 a 1.0 representando o relevo (0.1 = muito plano, 0.5 = ondulado, 0.9 = montanhoso).
        4. landmarks: Uma lista de 3 a 5 pontos de referência REAIS próximos (Rios, Rodovias, Silos, Cidades vizinhas, Reservas). 
           Para cada landmark, inclua 'name', 'type' (infrastructure, water, terrain, city) e uma breve 'description'.

        Seja preciso com os dados geográficos.
    `;

    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
            tools: [{googleMaps: {}}],
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    locationName: { type: Type.STRING },
                    report: { type: Type.STRING },
                    roughness: { type: Type.NUMBER },
                    landmarks: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                name: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['water', 'infrastructure', 'terrain', 'city'] },
                                description: { type: Type.STRING }
                            }
                        }
                    }
                }
            }
        },
    });

    if (response.text) {
        return JSON.parse(response.text) as TerrainAnalysis;
    }

    throw new Error("Falha ao analisar o terreno.");
};

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, PerspectiveCamera, Html, Stars } from '@react-three/drei';
import * as THREE from 'three';
import { analyzeTerrain } from '../services/geminiService';
import { TerrainAnalysis, Landmark } from '../types';
import GlobeIcon from './icons/GlobeIcon';
import MapPinIcon from './icons/MapPinIcon';
import SparkleIcon from './icons/SparkleIcon';

interface AgroMap3DProps {
    isOpen: boolean;
    onClose: () => void;
}

// Generates a heightmap based on roughness
const generateTerrainGeometry = (width: number, height: number, segments: number, roughness: number) => {
    const geometry = new THREE.PlaneGeometry(width, height, segments, segments);
    const positionAttribute = geometry.attributes.position;

    // Simple pseudo-random noise function for terrain generation
    // We want it deterministic per session but varied enough
    for (let i = 0; i < positionAttribute.count; i++) {
        const x = positionAttribute.getX(i);
        const y = positionAttribute.getY(i);

        // Combine frequencies for "natural" look
        // Base low frequency (hills)
        let z = Math.sin(x * 0.5) * Math.cos(y * 0.5) * 2 * roughness;
        // High frequency (noise)
        z += Math.sin(x * 2.5 + y * 1.5) * 0.5 * roughness;

        positionAttribute.setZ(i, z);
    }

    geometry.computeVertexNormals();
    return geometry;
};

const LandmarkMarker = ({ landmark, position }: { landmark: Landmark, position: [number, number, number] }) => {
    const [hovered, setHovered] = useState(false);

    const getColor = (type: string) => {
        switch(type) {
            case 'water': return '#3b82f6'; // Blue
            case 'infrastructure': return '#f59e0b'; // Amber
            case 'city': return '#ec4899'; // Pink
            default: return '#10b981'; // Emerald
        }
    };

    const color = getColor(landmark.type);

    return (
        <group position={position}>
            {/* The 3D Pin */}
            <mesh position={[0, 0.5, 0]} onClick={() => setHovered(!hovered)} onPointerOver={() => setHovered(true)} onPointerOut={() => setHovered(false)}>
                <coneGeometry args={[0.3, 0.8, 8]} />
                <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.5} />
            </mesh>
            <mesh position={[0, 0, 0]}>
                <cylinderGeometry args={[0.05, 0.05, 1]} />
                <meshBasicMaterial color={color} opacity={0.5} transparent />
            </mesh>

            {/* The HTML Label */}
            <Html distanceFactor={15} position={[0, 1.5, 0]} style={{ pointerEvents: 'none' }}>
                <div className={`transition-all duration-300 transform ${hovered ? 'scale-110 opacity-100' : 'scale-90 opacity-70'} flex flex-col items-center`}>
                    <div 
                        className="px-3 py-1.5 rounded-lg text-xs font-bold text-white shadow-lg whitespace-nowrap backdrop-blur-md border border-white/20"
                        style={{ backgroundColor: `${color}cc` }} // hex with alpha
                    >
                        {landmark.name}
                    </div>
                    {hovered && (
                         <div className="mt-1 bg-black/80 text-white text-[10px] p-2 rounded max-w-[150px] text-center backdrop-blur">
                            {landmark.description}
                         </div>
                    )}
                </div>
            </Html>
        </group>
    );
};

const TerrainMesh = ({ isScanning, roughness, landmarks }: { isScanning: boolean, roughness: number, landmarks: Landmark[] }) => {
    const meshRef = useRef<THREE.Mesh>(null!);

    // Regenerate geometry when roughness changes
    const geometry = useMemo(() => generateTerrainGeometry(24, 24, 48, roughness), [roughness]);

    // Generate positions for landmarks scattered on the terrain
    const landmarkPositions = useMemo(() => {
        return landmarks.map(() => {
            // Random position within grid bounds (-10 to 10)
            const x = (Math.random() - 0.5) * 16;
            const y = (Math.random() - 0.5) * 16;
            // Calculate Z height at this X,Y (approximate from our noise function logic)
            let z = Math.sin(x * 0.5) * Math.cos(y * 0.5) * 2 * roughness;
            z += Math.sin(x * 2.5 + y * 1.5) * 0.5 * roughness;
            return [x, y, z] as [number, number, number];
        });
    }, [landmarks, roughness]);

    useFrame((state) => {
        if (meshRef.current) {
            meshRef.current.rotation.z += 0.001;

            if (isScanning) {
                 // Scanning visual effect
                 const scale = 1 + Math.sin(state.clock.getElapsedTime() * 5) * 0.005;
                 meshRef.current.scale.set(scale, scale, 1);
            }
        }
    });

    return (
        <group rotation={[-Math.PI / 2, 0, 0]}>
            <mesh ref={meshRef} geometry={geometry}>
                <meshStandardMaterial 
                    color={isScanning ? "#34d399" : "#059669"} 
                    wireframe={true} 
                    transparent 
                    opacity={0.4}
                    emissive={isScanning ? "#10b981" : "#065f46"}
                    emissiveIntensity={isScanning ? 0.8 : 0.2}
                />
            </mesh>

            {/* Base Plane for filling gaps */}
            <mesh position={[0, 0, -0.5]}>
                <planeGeometry args={[100, 100]} />
                <meshBasicMaterial color="#022c22" transparent opacity={0.8} />
            </mesh>

            {/* Landmarks placed on the terrain */}
            {!isScanning && landmarks.map((landmark, i) => (
                <group key={i} rotation={[Math.PI / 2, 0, 0]}> {/* Counter-rotate the markers container so pins stand up relative to world Z */}
                     {/* Actually, since the parent group is rotated -90 X, 'up' inside here is Y local which is Z world. 
                         Wait, if parent is -90 X, then parent Y is World Z. Parent Z is World -Y. 
                         The logic below: we calculated positions x,y (on plane), z (height). 
                         Inside the rotated group, x is x, y is y (which is "back" in world), z is height (which is "up" in world relative to mesh normals). 
                         We want to place them at mesh local coordinates.
                     */}
                     <group position={[landmarkPositions[i][0], landmarkPositions[i][1], landmarkPositions[i][2]]}>
                        {/* We need to rotate the marker back so it points "Up" in world space */}
                        <group rotation={[-Math.PI / 2, 0, 0]}> {/* Undo parent rotation for the pin item itself? No, simpler to just rotate 90 */}
                            <group rotation={[Math.PI / 2, 0, 0]}>
                                 <LandmarkMarker landmark={landmark} position={[0,0,0]} />
                            </group>
                        </group>
                     </group>
                </group>
            ))}

             {/* Correct way to place items on a rotated plane: Just rely on the local coordinate system */}
             {!isScanning && landmarks.map((lm, i) => (
                 <group key={`lm-${i}`} position={[landmarkPositions[i][0], landmarkPositions[i][1], landmarkPositions[i][2]]}>
                     <group rotation={[Math.PI/2, 0, 0]}>
                        <LandmarkMarker landmark={lm} position={[0,0,0]} />
                     </group>
                 </group>
             ))}

            <Grid 
                position={[0, 0, -1]} 
                args={[40, 40]} 
                cellColor="#065f46" 
                sectionColor="#047857" 
                fadeDistance={25} 
                infiniteGrid 
            />
        </group>
    );
};

const AgroMap3D: React.FC<AgroMap3DProps> = ({ isOpen, onClose }) => {
    const [location, setLocation] = useState('');
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState<TerrainAnalysis | null>(null);

    const handleAnalyze = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!location.trim()) return;

        setLoading(true);
        setData(null);

        try {
            const result = await analyzeTerrain(location);
            setData(result);
        } catch (error) {
            console.error(error);
            // Fallback for demo if API fails or quota limited
            setData({
                locationName: location,
                report: "**Erro de conexão.** Não foi possível validar os dados reais no momento.",
                roughness: 0.1,
                landmarks: []
            });
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-90 backdrop-blur-md animate-fade-in overflow-hidden">
            <div className="relative w-full h-full flex flex-col md:flex-row">

