interface SplashScreenProps {
    onFinish: () => void;
}

const loadingSteps = [
    "Inicializando Sistemas...",
    "Calibrando Sensores IA...",
    "Conectando Satélites...",
    "Carregando Modelos...",
    "Bem-vindo ao Agroconecta"
