const SplashScreen: React.FC<SplashScreenProps> = ({ onFinish }) => {
    const [progress, setProgress] = useState(0);
    const [stepIndex, setStepIndex] = useState(0);
    const [isFadingOut, setIsFadingOut] = useState(false);

    useEffect(() => {
        // Progress bar animation
        const interval = setInterval(() => {
            setProgress((prev) => {
                if (prev >= 100) {
                    clearInterval(interval);
                    return 100;
                }
                // Randomize speed for "organic" feel
                return prev + Math.random() * 5;
            });
        }, 100);

        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        // Step text change logic based on progress thresholds
        if (progress < 30) setStepIndex(0);
        else if (progress < 50) setStepIndex(1);
        else if (progress < 75) setStepIndex(2);
        else if (progress < 95) setStepIndex(3);
        else setStepIndex(4);

        if (progress >= 100) {
            setTimeout(() => {
                setIsFadingOut(true);
                setTimeout(onFinish, 800); // Wait for fade out animation
            }, 500);
        }
    }, [progress, onFinish]);

    if (progress > 100 && !isFadingOut) return null;

    return (
        <div 
            className={`fixed inset-0 z-[100] flex flex-col items-center justify-center bg-gray-950 transition-opacity duration-1000 ease-in-out ${
                isFadingOut ? 'opacity-0 pointer-events-none' : 'opacity-100'
            }`}
        >
