import React, { useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const ParticleField = () => {
  const count = 1800; 
  const mesh = useRef<THREE.Points>(null!);

  // Monochrome Premium Palette
  const colorBase = new THREE.Color('#52525b'); // Zinc 600
  const colorHot = new THREE.Color('#ffffff'); // White
  const colorWhite = new THREE.Color('#e4e4e7'); // Zinc 200

  // Store particle data including velocity and original position
  const particles = useMemo(() => {
    const temp = [];
    for (let i = 0; i < count; i++) {
      const x = (Math.random() - 0.5) * 50; 
      const y = (Math.random() - 0.5) * 40;
      const z = (Math.random() - 0.5) * 15;

      temp.push({
        x, y, z, 
        originalX: x, originalY: y, originalZ: z,
        vx: 0, vy: 0, vz: 0,
        size: Math.random() * 0.12 + 0.02
      });
    }
    return temp;
  }, [count]);

  const { positions, colors, sizes } = useMemo(() => {
    const p = new Float32Array(count * 3);
    const c = new Float32Array(count * 3);
    const s = new Float32Array(count);

    for (let i = 0; i < count; i++) {
        p[i * 3] = particles[i].x;
        p[i * 3 + 1] = particles[i].y;
        p[i * 3 + 2] = particles[i].z;

        // Base color is dark gray
        c[i * 3] = colorBase.r;
        c[i * 3 + 1] = colorBase.g;
        c[i * 3 + 2] = colorBase.b;

        s[i] = particles[i].size;
    }
    return { positions: p, colors: c, sizes: s };
  }, [count, particles]);

  useFrame((state) => {
    const mouseX = (state.pointer.x * state.viewport.width) / 2;
    const mouseY = (state.pointer.y * state.viewport.height) / 2;

    const positionsArray = mesh.current.geometry.attributes.position.array as Float32Array;
    const colorsArray = mesh.current.geometry.attributes.color.array as Float32Array;

    for (let i = 0; i < count; i++) {
      const p = particles[i];

      const dx = mouseX - p.x;
      const dy = mouseY - p.y;
      const distSq = dx * dx + dy * dy;
      const dist = Math.sqrt(distSq);

      const repulsionRadius = 8; 
      const repulsionStrength = 2.0; 
      const returnStrength = 0.02; 
      const damping = 0.95; 

      if (dist < repulsionRadius) {
        const force = Math.pow((1 - dist / repulsionRadius), 2) * repulsionStrength;
        const angle = Math.atan2(dy, dx);

        p.vx -= Math.cos(angle) * force;
        p.vy -= Math.sin(angle) * force;
        p.vz += force * 0.3; 
      }

      p.vx += (p.originalX - p.x) * returnStrength;
      p.vy += (p.originalY - p.y) * returnStrength;
      p.vz += (p.originalZ - p.z) * returnStrength;

      p.vx *= damping;
      p.vy *= damping;
      p.vz *= damping;

      p.x += p.vx;
      p.y += p.vy;
      p.z += p.vz;

      const speed = Math.sqrt(p.vx * p.vx + p.vy * p.vy + p.vz * p.vz);

      let r, g, b;
      if (speed > 0.05) {
          const t = Math.min((speed - 0.05) * 4, 1); 
          r = THREE.MathUtils.lerp(colorBase.r, colorHot.r, t);
          g = THREE.MathUtils.lerp(colorBase.g, colorHot.g, t);
          b = THREE.MathUtils.lerp(colorBase.b, colorHot.b, t);
      } else {
          // Subtle breathing effect
          const time = state.clock.getElapsedTime();
          const pulse = Math.sin(time + p.originalX) * 0.2 + 0.8;
          r = colorBase.r * pulse;
          g = colorBase.g * pulse;
          b = colorBase.b * pulse;
      }

      colorsArray[i * 3] = r;
      colorsArray[i * 3 + 1] = g;
      colorsArray[i * 3 + 2] = b;

      const time = state.clock.getElapsedTime();
      p.x += Math.sin(time * 0.2 + p.originalY) * 0.005;
      p.y += Math.cos(time * 0.1 + p.originalX) * 0.005;

      positionsArray[i * 3] = p.x;
      positionsArray[i * 3 + 1] = p.y;
      positionsArray[i * 3 + 2] = p.z;
    }

    mesh.current.geometry.attributes.position.needsUpdate = true;
    mesh.current.geometry.attributes.color.needsUpdate = true;

    mesh.current.rotation.y = Math.sin(state.clock.getElapsedTime() * 0.05) * 0.02;
  });

  return (
    <points ref={mesh}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={positions.length / 3}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={colors.length / 3}
          array={colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.12}
        vertexColors={true}
        sizeAttenuation={true}
        transparent={true}
        opacity={0.9}
        blending={THREE.AdditiveBlending}
        depthWrite={false}
      />
    </points>
  );
};

