export default function App() {
    const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
    const [showSplash, setShowSplash] = useState(true);

    const [imageFile, setImageFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [promptCount, setPromptCount] = useState<number>(0);
    const [isSubscribed, setIsSubscribed] = useState<boolean>(false);
    const [isCheckoutOpen, setIsCheckoutOpen] = useState<boolean>(false);

    const [isProfileOpen, setIsProfileOpen] = useState<boolean>(false);
    const [userProfile, setUserProfile] = useState<UserProfileType>({
        farmName: '',
        location: '',
        crops: [],
        history: []
    });

    const [isTutorialOpen, setIsTutorialOpen] = useState<boolean>(false);
    const [isPastoConectaOpen, setIsPastoConectaOpen] = useState<boolean>(false);
    const [isAgroMapOpen, setIsAgroMapOpen] = useState<boolean>(false);

    useEffect(() => {
        try {
            const storedAuth = localStorage.getItem('agroconectaIsAuthenticated');
            const storedCount = localStorage.getItem('agroconectaPromptCount');
            const storedSubscribed = localStorage.getItem('agroconectaIsSubscribed');
            const storedProfile = localStorage.getItem('agroconectaProfile');

            if (storedAuth === 'true') setIsAuthenticated(true);
            if (storedCount) setPromptCount(parseInt(storedCount, 10));
            if (storedSubscribed === 'true') setIsSubscribed(true);
            if (storedProfile) setUserProfile(JSON.parse(storedProfile));
        } catch (error) {
            console.error("Failed to access localStorage.", error);
        }
    }, []);

    const handleLogin = () => {
        setIsAuthenticated(true);
        localStorage.setItem('agroconectaIsAuthenticated', 'true');
    };

    const handleUpdateProfile = (newProfile: UserProfileType) => {
        setUserProfile(newProfile);
        try {
            localStorage.setItem('agroconectaProfile', JSON.stringify(newProfile));
        } catch (e) {
            console.error("Failed to save profile", e);
        }
    };

    const handleImageSelect = useCallback((file: File) => {
        setImageFile(file);
        setPreviewUrl(URL.createObjectURL(file));
        setAnalysisResult(null);
        setError(null);
    }, []);

    const handleAnalyze = async () => {
        if (!imageFile) return;

        if (!isSubscribed && promptCount >= FREE_PROMPT_LIMIT) {
            setError("Você atingiu o limite de 3 análises gratuitas. Assine para continuar.");
            return;
        }

        setLoading(true);
        setError(null);
        setAnalysisResult(null);

        try {
            const result = await analyzeCrop(imageFile, userProfile.location);
            setAnalysisResult(result);

            if (!isSubscribed) {
                const newCount = promptCount + 1;
                setPromptCount(newCount);
                localStorage.setItem('agroconectaPromptCount', newCount.toString());
            }

            const newHistoryItem = {
                id: Date.now().toString(),
                timestamp: Date.now(),
                result: result
            };

            const updatedProfile = {
                ...userProfile,
                history: [...userProfile.history, newHistoryItem]
            };
            handleUpdateProfile(updatedProfile);

        } catch (e: any) {
            console.error(e);
            if (e.message && (e.message.includes('403') || e.message.includes('API key'))) {
                 setError("Erro de configuração da API. Verifique se sua chave está correta na Vercel.");
            } else {
                 setError("Ocorreu um erro ao analisar a imagem. Por favor, tente novamente.");
            }
        } finally {
            setLoading(false);
        }
    };

    const handleClear = () => {
        setImageFile(null);
        setPreviewUrl(null);
        setAnalysisResult(null);
        setError(null);
    };

    const handleOpenCheckout = () => {
        setIsCheckoutOpen(true);
    };

    const handlePaymentSuccess = () => {
        setIsSubscribed(true);
        localStorage.setItem('agroconectaIsSubscribed', 'true');
        setError(null);
        setTimeout(() => {
            setIsCheckoutOpen(false);
        }, 1500);
    };

    const promptsRemaining = FREE_PROMPT_LIMIT - promptCount;
    const canAnalyze = isSubscribed || promptCount < FREE_PROMPT_LIMIT;

    return (
        <div className="min-h-screen bg-black text-white font-sans flex flex-col relative selection:bg-white selection:text-black overflow-x-hidden">
            <Background3D />

            {showSplash ? (
                <SplashScreen onFinish={() => setShowSplash(false)} />
            ) : !isAuthenticated ? (
                <LoginScreen onLogin={handleLogin} />
            ) : (
                <>
                    <header className="sticky top-0 z-30 bg-black/80 backdrop-blur-xl border-b border-white/5 transition-all duration-300 pointer-events-none">
                        <div className="container mx-auto px-6 py-4 flex items-center justify-between pointer-events-auto">
                            <div className="flex items-center gap-3 cursor-pointer group" onClick={() => window.location.reload()}>
                                <div className="bg-white/10 p-2 rounded-lg border border-white/10 group-hover:border-white/40 transition-colors">
                                    <SparkleIcon className="w-5 h-5 text-white" />
                                </div>
                                <h1 className="text-xl font-light tracking-widest hidden sm:block text-white">
                                    AGRO<span className="font-bold">CONECTA</span>
                                </h1>
                            </div>

                            <div className="flex items-center gap-4">
                                <div className="hidden sm:flex items-center">
                                    {isSubscribed ? (
                                        <span className="inline-flex items-center px-3 py-1 rounded-full text-[10px] font-bold bg-white text-black shadow-glow-sm uppercase tracking-wide">
                                            <SparkleIcon className="w-3 h-3 mr-1.5" />
                                            Premium
                                        </span>
                                    ) : (
                                        <div className="bg-zinc-900 px-3 py-1 rounded-full border border-zinc-800 flex items-center gap-2">
                                            <span className="text-[10px] font-mono text-zinc-500 uppercase">Credits</span>
                                            <span className="font-mono text-white text-xs">{promptsRemaining < 0 ? 0 : promptsRemaining}</span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex items-center gap-2">
                                    {[
                                        { icon: GlobeIcon, action: () => setIsAgroMapOpen(true), title: "Maps" },
                                        { icon: CowIcon, action: () => setIsPastoConectaOpen(true), title: "Market" },
                                        { icon: UserIcon, action: () => setIsProfileOpen(true), title: "Profile" }
                                    ].map((btn, i) => (
                                        <button
                                            key={i}
                                            onClick={btn.action}
                                            className="relative p-2.5 rounded-lg bg-zinc-900/50 border border-zinc-800 hover:bg-zinc-800 hover:border-zinc-600 text-zinc-400 hover:text-white transition-all duration-300"
                                            title={btn.title}
