import React, { useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const DataGlobe = () => {
  const mesh = useRef<THREE.Points>(null!);
  const count = 2500;

  // Create points on a sphere surface
  const { positions, colors, sizes } = useMemo(() => {
    const p = new Float32Array(count * 3);
    const c = new Float32Array(count * 3);
    const s = new Float32Array(count);

    const colorBase = new THREE.Color('#3f3f46'); // Zinc 700
    const colorHighlight = new THREE.Color('#ffffff'); // White

    for (let i = 0; i < count; i++) {
        // Spherical coordinates
        const phi = Math.acos(-1 + (2 * i) / count);
        const theta = Math.sqrt(count * Math.PI) * phi;

        const r = 10; // Radius

        p[i * 3] = r * Math.cos(theta) * Math.sin(phi);
        p[i * 3 + 1] = r * Math.sin(theta) * Math.sin(phi);
        p[i * 3 + 2] = r * Math.cos(phi);

        // Randomly highlight some points to look like "active cities" or data nodes
        const isHighlight = Math.random() > 0.95;
        const color = isHighlight ? colorHighlight : colorBase;

        c[i * 3] = color.r;
        c[i * 3 + 1] = color.g;
        c[i * 3 + 2] = color.b;

        s[i] = isHighlight ? Math.random() * 0.15 + 0.05 : 0.05;
    }
    return { positions: p, colors: c, sizes: s };
  }, [count]);

  useFrame((state) => {
    if (mesh.current) {
        // Slow rotation
        mesh.current.rotation.y = state.clock.getElapsedTime() * 0.05;
        mesh.current.rotation.x = Math.sin(state.clock.getElapsedTime() * 0.1) * 0.1;
    }
  });

  return (
    <points ref={mesh}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={positions.length / 3}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={colors.length / 3}
          array={colors}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-size"
          count={sizes.length}
          array={sizes}
          itemSize={1}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.1}
        vertexColors={true}
        transparent={true}
        opacity={0.6}
        sizeAttenuation={true}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
};

const ConnectionLines = () => {
    const linesRef = useRef<THREE.Group>(null!);

    useFrame((state) => {
        if (linesRef.current) {
             linesRef.current.rotation.y = state.clock.getElapsedTime() * 0.05;
             linesRef.current.rotation.x = Math.sin(state.clock.getElapsedTime() * 0.1) * 0.1;
        }
    });

    // Create a few curved lines representing satellite connections
    return (
        <group ref={linesRef}>
             <mesh rotation={[0,0,0]}>
                <ringGeometry args={[10.1, 10.15, 64]} />
                <meshBasicMaterial color="#ffffff" opacity={0.05} transparent side={THREE.DoubleSide} />
             </mesh>
             <mesh rotation={[1,1,0]}>
                <ringGeometry args={[10.1, 10.15, 64]} />
                <meshBasicMaterial color="#ffffff" opacity={0.05} transparent side={THREE.DoubleSide} />
