                    ${isDragOver ? 'border-white bg-white/5 scale-[1.01]' : 'border-zinc-700 hover:border-zinc-500 bg-black/20'}`}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                >
                    <input
                        type="file"
                        accept="image/*"
                        onChange={handleFileChange}
                        ref={fileInputRef}
                        className="hidden"
                        disabled={disabled}
                    />

                    <div className="flex flex-col w-full gap-4">
