export default function App() {
    // Auth State pulled from DB
    const [isAuthenticated, setIsAuthenticated] = useState<boolean>(db.user.isAuthenticated());
    const [showIntro, setShowIntro] = useState(true);

    const [imageFile, setImageFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);

    // DB synced states
    const [promptCount, setPromptCount] = useState<number>(() => {
        return parseInt(localStorage.getItem('agroconectaPromptCount') || '0');
    });
    const [isSubscribed, setIsSubscribed] = useState<boolean>(() => {
        return localStorage.getItem('agroconectaIsSubscribed') === 'true';
    });
    const [userProfile, setUserProfile] = useState<UserProfileType>(db.user.getProfile());

    const [isCheckoutOpen, setIsCheckoutOpen] = useState<boolean>(false);
    const [isProfileOpen, setIsProfileOpen] = useState<boolean>(false);
    const [isTutorialOpen, setIsTutorialOpen] = useState<boolean>(false);
    const [isPastoConectaOpen, setIsPastoConectaOpen] = useState<boolean>(false);
    const [isAgroMapOpen, setIsAgroMapOpen] = useState<boolean>(false);

    const handleLogin = () => {
        db.user.login();
        setIsAuthenticated(true);
    };

    const handleUpdateProfile = (newProfile: UserProfileType) => {
        setUserProfile(newProfile);
        db.user.updateProfile(newProfile);
    };

    const handleImageSelect = useCallback((file: File) => {
        setImageFile(file);
        setPreviewUrl(URL.createObjectURL(file));
        setAnalysisResult(null);
        setError(null);
    }, []);

    const handleAnalyze = async () => {
        if (!imageFile) return;

        if (!isSubscribed && promptCount >= FREE_PROMPT_LIMIT) {
            setError("Limite de crédito atingido. Atualização necessária.");
            return;
        }

        setLoading(true);
        setError(null);
        setAnalysisResult(null);

        try {
            const result = await analyzeCrop(imageFile, userProfile.location);
            setAnalysisResult(result);

            if (!isSubscribed) {
                const newCount = promptCount + 1;
                setPromptCount(newCount);
                localStorage.setItem('agroconectaPromptCount', newCount.toString());
            }

            db.user.addHistoryItem(result);
            setUserProfile(db.user.getProfile()); // Sync UI

        } catch (e: any) {
            console.error(e);
            if (e.message && (e.message.includes('403') || e.message.includes('API key'))) {
                 setError("Erro do Sistema: Configuração de API Inválida.");
            } else {
                 setError("Falha na análise. Por favor, tente novamente.");
            }
        } finally {
            setLoading(false);
        }
    };

    const handleClear = () => {
        setImageFile(null);
        setPreviewUrl(null);
        setAnalysisResult(null);
        setError(null);
    };

    const handleOpenCheckout = () => {
        setIsCheckoutOpen(true);
    };

    const handlePaymentSuccess = () => {
        setIsSubscribed(true);
        localStorage.setItem('agroconectaIsSubscribed', 'true');
        setError(null);
        setTimeout(() => {
            setIsCheckoutOpen(false);
        }, 1500);
    };

    const promptsRemaining = FREE_PROMPT_LIMIT - promptCount;
    const canAnalyze = isSubscribed || promptCount < FREE_PROMPT_LIMIT;

    return (
        <div className="min-h-screen bg-black text-white font-sans flex flex-col relative selection:bg-white selection:text-black overflow-x-hidden">
            <Background3D />

            {showIntro ? (
                <IntroAnimation onFinish={() => setShowIntro(false)} />
            ) : !isAuthenticated ? (
                <LoginScreen onLogin={handleLogin} />
            ) : (
                <>
                    <header className="sticky top-0 z-30 bg-black/80 backdrop-blur-xl border-b border-white/5 transition-all duration-300 pointer-events-none">
                        <div className="container mx-auto px-6 py-4 flex items-center justify-between pointer-events-auto">
                            <div className="flex items-center gap-3 cursor-pointer group" onClick={() => window.location.reload()}>
                                <div className="bg-white/10 p-2 rounded-lg border border-white/10 group-hover:border-white/40 transition-colors">
                                    <SparkleIcon className="w-5 h-5 text-white" />
                                </div>
                                <h1 className="text-xl font-light tracking-widest hidden sm:block text-white">
                                    AGRO<span className="font-bold">CONECTA</span>
                                </h1>
                            </div>

                            <div className="flex items-center gap-4">
                                <div className="hidden sm:flex items-center">
                                    {isSubscribed ? (
                                        <span className="inline-flex items-center px-3 py-1 rounded-full text-[10px] font-bold bg-white text-black shadow-glow-sm uppercase tracking-wide">
                                            <SparkleIcon className="w-3 h-3 mr-1.5" />
                                            Premium
                                        </span>
                                    ) : (
                                        <div className="bg-zinc-900 px-3 py-1 rounded-full border border-zinc-800 flex items-center gap-2">
                                            <span className="text-[10px] font-mono text-zinc-500 uppercase">Créditos</span>
                                            <span className="font-mono text-white text-xs">{promptsRemaining < 0 ? 0 : promptsRemaining}</span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex items-center gap-2">
                                    {[
                                        { icon: GlobeIcon, action: () => setIsAgroMapOpen(true), title: "Mapas" },
                                        { icon: CowIcon, action: () => setIsPastoConectaOpen(true), title: "Mercado" },
                                        { icon: UserIcon, action: () => setIsProfileOpen(true), title: "Perfil" }
                                    ].map((btn, i) => (
                                        <button
                                            key={i}
                                            onClick={btn.action}
                                            className="relative p-2.5 rounded-lg bg-zinc-900/50 border border-zinc-800 hover:bg-zinc-800 hover:border-zinc-600 text-zinc-400 hover:text-white transition-all duration-300"
                                            title={btn.title}
                                        >
                                            <btn.icon className="w-5 h-5" />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </header>

                    <main className="container mx-auto p-4 md:p-8 flex flex-col items-center flex-grow w-full max-w-5xl z-10 relative pointer-events-none">
                        {!previewUrl && (
                            canAnalyze ? (
                                <div className="w-full py-16">
                                    <ImageSelector 
                                        onImageSelect={handleImageSelect} 
                                        disabled={loading} 
                                        onOpenTutorial={() => setIsTutorialOpen(true)}
                                    />
                                </div>
                            ) : (
                                <div className="w-full py-16">
                                    <SubscriptionPrompt onSubscribe={handleOpenCheckout} />
                                </div>
                            )
                        )}

                        {error && (
                            <div className="mt-6 bg-red-950/50 border border-red-900 text-red-200 px-6 py-4 rounded-xl relative w-full max-w-lg text-center animate-fade-in backdrop-blur-md pointer-events-auto font-light" role="alert">
                                {error}
                            </div>
                        )}

                        {previewUrl && !analysisResult && (
                            <div className="w-full max-w-4xl mt-8 animate-fade-in-up pointer-events-auto">
                                <div className="bg-black/80 backdrop-blur-xl rounded-3xl shadow-2xl overflow-hidden border border-white/10 flex flex-col md:flex-row">

                                    <div className="md:w-1/2 bg-zinc-900/50 flex items-center justify-center p-8 relative">
                                        <img src={previewUrl} alt="Preview" className="rounded-xl shadow-2xl max-h-[400px] object-contain relative z-10 border border-white/5" />
                                        <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent pointer-events-none"></div>
                                    </div>

                                    <div className="md:w-1/2 p-10 flex flex-col justify-center">
                                        <h2 className="text-2xl font-light text-white mb-8">Scan Pronto</h2>
                                        <div className="space-y-4">
                                            <button
                                                onClick={handleAnalyze}
                                                disabled={loading || !canAnalyze}
                                                className="w-full group relative overflow-hidden rounded-xl bg-white px-6 py-4 text-black shadow-glow transition-all hover:scale-[1.02] disabled:opacity-50"
                                            >
                                                <div className="relative z-10 flex items-center justify-center text-sm font-bold uppercase tracking-widest">
                                                    <SparkleIcon className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                                                    {loading ? 'Processando...' : 'Iniciar Análise'}
                                                </div>
                                            </button>

                                            <button
                                                onClick={handleClear}
                                                disabled={loading}
                                                className="w-full rounded-xl bg-transparent border border-zinc-700 px-6 py-4 text-zinc-300 font-medium transition-all hover:bg-zinc-900 hover:text-white hover:border-zinc-500"
                                            >
                                                Nova Imagem
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {loading && <LoadingSpinner />}
                        {analysisResult && <AnalysisDisplay result={analysisResult} />}

                    </main>
                    <Footer />

                    <CheckoutModal 
                        isOpen={isCheckoutOpen} 
                        onClose={() => setIsCheckoutOpen(false)} 
                        onSuccess={handlePaymentSuccess} 
                    />

                    <UserProfile 
                        isOpen={isProfileOpen}
                        onClose={() => setIsProfileOpen(false)}
                        profile={userProfile}
                        onUpdateProfile={handleUpdateProfile}
                    />

                    <PastoConecta
                        isOpen={isPastoConectaOpen}
                        onClose={() => setIsPastoConectaOpen(false)}
                    />

                    <AgroMap3D
                        isOpen={isAgroMapOpen}
                        onClose={() => setIsAgroMapOpen(false)}
                    />

                    <TutorialModal
                        isOpen={isTutorialOpen}
                        onClose={() => setIsTutorialOpen(false)}
                    />
                </>
            )}
        </div>
    );
}

