import React, { useEffect, useState, useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, Stars, PerspectiveCamera, Trail, Line, Text, Plane } from '@react-three/drei';
import * as THREE from 'three';
import SparkleIcon from './icons/SparkleIcon';
import CameraIcon from './icons/CameraIcon';
import MapPinIcon from './icons/MapPinIcon';
import GlobeIcon from './icons/GlobeIcon';

// --- 3D Scenes ---

// Phase 0: DNA Helix (Biotech/Culture)
const DnaHelix = () => {
    const pointsRef = useRef<THREE.Points>(null!);
    const count = 100; // Number of base pairs

    const { positions, colors } = useMemo(() => {
        const positions = [];
        const colors = [];
        const color1 = new THREE.Color('#4ade80'); // Green
        const color2 = new THREE.Color('#3b82f6'); // Blue

        for (let i = 0; i < count; i++) {
            const t = i * 0.3;
            // Strand 1
            positions.push(Math.sin(t), i * 0.1 - 5, Math.cos(t));
            colors.push(color1.r, color1.g, color1.b);

            // Strand 2
            positions.push(Math.sin(t + Math.PI), i * 0.1 - 5, Math.cos(t + Math.PI));
            colors.push(color2.r, color2.g, color2.b);
        }
        return { 
            positions: new Float32Array(positions.flat()), 
            colors: new Float32Array(colors.flat()) 
        };
    }, []);

    useFrame((state) => {
        if (pointsRef.current) {
            pointsRef.current.rotation.y = state.clock.getElapsedTime() * 0.5;
            pointsRef.current.position.y = Math.sin(state.clock.getElapsedTime() * 0.5) * 0.5;
        }
    });

    return (
        <group>
            <points ref={pointsRef}>
                <bufferGeometry>
                    <bufferAttribute attach="attributes-position" count={positions.length / 3} array={positions} itemSize={3} />
                    <bufferAttribute attach="attributes-color" count={colors.length / 3} array={colors} itemSize={3} />
                </bufferGeometry>
                <pointsMaterial size={0.15} vertexColors transparent opacity={0.8} sizeAttenuation depthWrite={false} />
            </points>
            {/* Connecting lines for base pairs (visual simulation) */}
             <mesh rotation={[0,0,0]} position={[0,0,0]}>
                 <cylinderGeometry args={[0.2, 0.2, 10, 8]} />
                 <meshBasicMaterial color="#4ade80" wireframe opacity={0.05} transparent />
             </mesh>
        </group>
    );
};

// Phase 1: Optical Lens Scanner (Vision)
const OpticalScanner = () => {
    const ring1 = useRef<THREE.Mesh>(null!);
    const ring2 = useRef<THREE.Mesh>(null!);
    const ring3 = useRef<THREE.Mesh>(null!);

    useFrame((state) => {
        const t = state.clock.getElapsedTime();
        ring1.current.rotation.x = Math.sin(t * 0.5);
        ring1.current.rotation.y = t * 0.2;

        ring2.current.rotation.x = Math.cos(t * 0.3);
        ring2.current.rotation.z = t * 0.1;

        ring3.current.rotation.z = -t * 0.4;

        // Pulse scale effect
        const scale = 1 + Math.sin(t * 5) * 0.02;
        ring3.current.scale.set(scale, scale, scale);
    });

    return (
        <group>
            {/* Outer Ring */}
            <mesh ref={ring1}>
                <torusGeometry args={[2.5, 0.02, 16, 100]} />
                <meshBasicMaterial color="#ffffff" transparent opacity={0.3} />
            </mesh>
            {/* Middle Tech Ring */}
            <mesh ref={ring2}>
                <torusGeometry args={[2, 0.05, 16, 6]} />
                <meshStandardMaterial color="#3b82f6" emissive="#3b82f6" emissiveIntensity={2} />
            </mesh>
            {/* Inner Focus Ring */}
            <mesh ref={ring3}>
                <torusGeometry args={[1.5, 0.03, 16, 100]} />
                <meshBasicMaterial color="#4ade80" />
                <group rotation={[0,0,Math.PI/2]}>
                     <mesh position={[1.5, 0, 0]}>
                         <boxGeometry args={[0.2, 0.1, 0.1]} />
                         <meshBasicMaterial color="red" />
                     </mesh>
                     <mesh position={[-1.5, 0, 0]}>
                         <boxGeometry args={[0.2, 0.1, 0.1]} />
                         <meshBasicMaterial color="red" />
                     </mesh>
                </group>
            </mesh>
            {/* Center Lens */}
            <mesh>
                <sphereGeometry args={[1, 32, 32]} />
                <meshPhysicalMaterial 
                    roughness={0} 
                    transmission={1} 
                    thickness={0.5} 
                    color="#ffffff"
                    ior={1.5}
                />
            </mesh>
        </group>
    );
};

// Phase 2: Terrain Laser Scan (Mapping)
const ScanningTerrain = () => {
    const laserRef = useRef<THREE.Mesh>(null!);

    useFrame((state) => {
        // Move laser back and forth
