const CinematicCamera = ({ phase }: { phase: number }) => {
    const cam = useRef<THREE.PerspectiveCamera>(null!);

    useFrame((state) => {
        // Smooth interpolation of camera position based on phase
        const targetPos = new THREE.Vector3(0, 0, 8); // Default

        if (phase === 0) targetPos.set(0, 0, 6); // Close up on DNA
        if (phase === 1) targetPos.set(0, 0, 7); // Scanner
        if (phase === 2) targetPos.set(0, 2, 6); // Angle for terrain
        if (phase === 3) targetPos.set(0, 0, 9); // Wide for globe

        state.camera.position.lerp(targetPos, 0.05);
        state.camera.lookAt(0, 0, 0);
    });

    return null;
}

