import { GoogleGenAI, Type } from "@google/genai";
import type { GroundingChunk, AnalysisResult, TerrainAnalysis } from '../types';

// Initialization following Google GenAI SDK strict guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToGenerativePart = async (file: File) => {
  const base64EncodedDataPromise = new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: { data: await base64EncodedDataPromise, mimeType: file.type },
  };
};

export const analyzeCrop = async (imageFile: File, userLocation?: string): Promise<AnalysisResult> => {
    // Task 1: Analyze the image for pests/diseases
    const imageAnalysisPromise = async () => {
        const imagePart = await fileToGenerativePart(imageFile);

        // Novo prompt "Motor de Diagnóstico Fitossanitário AgroConecta"
        const prompt = `
            Papel: Você é o motor de diagnóstico fitossanitário do AgroConecta. Sua função é analisar dados de campo e imagens para identificar qualquer anormalidade em qualquer cultura, utilizando um processo de análise clínica por etapas para eliminar falsos diagnósticos.

            ETAPA 1: PROCESSAMENTO DA FICHA DE ANAMNESE (Inferência Visual)
            Cruze os dados visuais para deduzir:
            - Hospedeiro: Identificar cultura, idade da planta e vigor.
            - Ambiente: Analisar sinais de umidade, temperatura (estresse) ou chuvas recentes (janela de infecção).
            - Manejo: Verificar intervenções humanas, densidade ou resíduos químicos.
            - Tempo: Avaliar se os sintomas parecem agudos ou crônicos.

            ETAPA 2: PROTOCOLO DE ANÁLISE VISUAL
            (Nota: O usuário forneceu apenas uma imagem. Faça o melhor diagnóstico possível com este dado, mas mencione limitações se necessário).
            Analise buscando:
            1. Contexto/Área: Diferenciar problemas de solo/clima (distribuição uniforme) de problemas bióticos (focos/reboleiras).
            2. Detalhe do Sintoma: Morfologia da lesão, coloração e bordas (halos).
            3. Estruturas de Reprodução: Sinais diretos do patógeno (esporos, micélios, pústulas) ou presença de pragas.

            ETAPA 3: LÓGICA DE DIAGNÓSTICO DIFERENCIAL (Triagem de Exclusão)
            Obrigatoriamente realize mentalmente:
            - Sintoma Visual vs. Sinal Físico: Se houver lesão mas não houver sinal físico do patógeno, considere causas abióticas (nutrição/fitotoxicidade).
            - Análise de Localização: Verifique se o dano é localizado (manchas/cancros), sistêmico (murchas) ou morfológico (deformações/viroses).
            - Filtro de Probabilidade: Cruze o diagnóstico visual com o Ambiente inferido. Se o patógeno suspeito não sobrevive nas condições aparentes, desça o nível de confiança.

            ETAPA 4: ESTRUTURA DO RELATÓRIO DE SAÍDA
            Sua resposta deve ser estruturada ESTRITAMENTE com os cabeçalhos Markdown abaixo para ser processada pelo aplicativo:

            ## 🔍 Diagnóstico
            [Diagnóstico Principal: Nome comum e científico do agente causador]
            [Nível de Confiança: (0% a 100%)]

            ## 📝 Sintomas Identificados
            [Justificativa Técnica: Explique como o Hospedeiro, Ambiente e Manejo convergiram para este problema. Descreva a morfologia observada.]

            ## 🔬 Diagnóstico Diferencial
            [Diferencial de Segurança: Liste quais outras doenças comuns naquela cultura foram descartadas e o porquê (com base nas fotos/lógica da Etapa 3).]

            ## 💊 Tratamento Recomendado
            [Sugestão de Manejo: Medidas culturais e técnicas. Cite a necessidade de validação de um Engenheiro Agrônomo e Receituário Agronômico.]

            ## 🛡️ Medidas Preventivas
            [Estratégias para evitar reincidência.]

            DIRETRIZES DE SEGURANÇA
            - Inconclusividade: Se o sintoma for dúbio ou a imagem ruim, declare em Diagnóstico: "Dados insuficientes para diagnóstico preciso" e especifique qual ângulo ou informação falta.
            - Foco em Plantas: Mantenha a análise estritamente no reino vegetal e culturas agrícolas. Se não for planta, responda apenas: "Imagem inválida: Não foi possível identificar uma cultura agrícola."
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: [{ parts: [imagePart, {text: prompt}] }],
        });

        // Use response.text as a property, not a method
        return response.text || "Não foi possível gerar a análise.";
    };

    // Task 2: Find nearby stores using Maps Grounding based on user location
    const findStoresPromise = async () => {
        const locationQuery = userLocation && userLocation.trim() !== '' 
            ? `perto de ${userLocation}` 
            : "próximas a minha localização atual";

        const prompt = `Liste casas agropecuárias ${locationQuery}.`;

        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                tools: [{googleMaps: {}}],
            },
        });

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

        // Use response.text as a property
        return {
            storesText: response.text || "Não foi possível encontrar lojas.",
            groundingChunks: groundingChunks as GroundingChunk[]
        };
    };

    const [diagnosis, storesData] = await Promise.all([
        imageAnalysisPromise(),
        findStoresPromise(),
    ]);

    return {
        diagnosis,
        stores: storesData.storesText,
        groundingChunks: storesData.groundingChunks
    };
};

export const analyzeTerrain = async (location: string): Promise<TerrainAnalysis> => {
    // NOTA: Ao usar googleMaps tool, NÃO PODEMOS usar responseMimeType: "application/json".
    // Devemos instruir o modelo via texto a retornar JSON.
    const prompt = `
        Você é um sistema de topografia avançado. Analise a região de: "${location}".
        Use a ferramenta Google Maps para encontrar dados REAIS sobre a geografia, hidrografia e infraestrutura próxima.

        Responda APENAS com um objeto JSON válido (sem markdown \`\`\`json ... \`\`\` se possível, ou dentro dele), seguindo rigorosamente esta estrutura:

        {
            "locationName": "Nome formal da cidade/região encontrada",
            "report": "Um relatório técnico agronômico detalhado (Markdown) cobrindo Clima, Relevo, Solo estimado e Culturas indicadas.",
            "roughness": 0.5, 
            "landmarks": [
                {
                    "name": "Nome do ponto de referência",
                    "type": "water", 
                    "description": "Breve descrição"
                }
            ]
        }

        Regras para os campos:
        - "roughness": número float de 0.0 (plano) a 1.0 (muito montanhoso).
        - "landmarks": Lista de 3 a 5 pontos reais próximos.
        - "landmarks[].type": deve ser estritamente um destes: 'water', 'infrastructure', 'terrain', 'city'.
    `;

    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
            tools: [{googleMaps: {}}],
            // REMOVIDO: responseMimeType e responseSchema (incompatíveis com googleMaps tool)
        },
    });

    if (response.text) {
        try {
            // Tenta limpar blocos de código Markdown caso o modelo os inclua
            let jsonString = response.text.trim();
            const match = jsonString.match(/\{[\s\S]*\}/);
            if (match) {
                jsonString = match[0];
            }

            return JSON.parse(jsonString) as TerrainAnalysis;
        } catch (e) {
            console.error("Failed to parse JSON from terrain analysis", e, response.text);

            // Fallback manual se o JSON falhar, para não quebrar a UI
            return {
                locationName: location,
                report: response.text, // Retorna o texto cru como relatório
                roughness: 0.5,
                landmarks: []
            };
        }
    }

    throw new Error("Falha ao analisar o terreno: Sem resposta do modelo.");
};

