            - Inconclusividade: Se o sintoma for dúbio ou a imagem ruim, declare em Diagnóstico: "Dados insuficientes para diagnóstico preciso" e especifique qual ângulo ou informação falta.
            - Foco em Plantas: Mantenha a análise estritamente no reino vegetal e culturas agrícolas. Se não for planta, responda apenas: "Imagem inválida: Não foi possível identificar uma cultura agrícola."
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: [{ parts: [imagePart, {text: prompt}] }],
        });

        // Use response.text as a property, not a method
        return response.text || "Não foi possível gerar a análise.";
    };

    // Task 2: Find nearby stores using Maps Grounding based on user location
    const findStoresPromise = async () => {
        const locationQuery = userLocation && userLocation.trim() !== '' 
            ? `perto de ${userLocation}` 
            : "próximas a minha localização atual";

        const prompt = `Liste casas agropecuárias ${locationQuery}.`;

        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                tools: [{googleMaps: {}}],
            },
        });

